// Фикстура-канон и одновременно проверка разбора: угловой каст `<string>value` — законный
// TypeScript, но он неотличим от JSX-элемента. Разбор `.ts` идёт БЕЗ плагина `jsx` именно
// ради этой строки; включи его для всех расширений — и здесь появится ошибка парсера на
// ровном месте.
export const widen = (value: unknown) => (<string>value).length;
